model.component("comp1").physics().create("gop", "GeometricalOptics", "geom1");
model.component("comp1").physics("gop").prop("IntensityComputation").set("IntensityComputation", "ComputeIntensityAndPower");
model.component("comp1").physics("gop").prop("ComputeOpticalPathLength").setIndex("ComputeOpticalPathLength", true, 0);
// Application Libraries: Ray_Optics_Module/Lenses_Cameras_and_Telescopes/double_gauss_lens, Ray_Optics_Module/Structural_Thermal_Optical_Performance_Analysis/thermally_induced_focal_shift

model.component("comp1").physics("gop").create("matd2", "MaterialDiscontinuity", 2);
model.component("comp1").physics("gop").feature("matd2").set("ThinDielectricFilmsOnBoundary", "AddLayersToSurface");
model.component("comp1").physics("gop").feature("matd2").create("film1", "ThinDielectricFilm", 2);
// Application Libraries: Ray_Optics_Module/Prisms_and_Coatings/antireflective_coating_multilayer, distributed_bragg_reflector, achromatic_phase_shifter

Image detector that only counts rays after at least one reflection:
model.component("comp1").physics("gop").create("wall2", "Wall", 2);
model.component("comp1").physics("gop").feature("wall2").set("WallCondition", "Freeze");
model.component("comp1").physics("gop").feature("wall2").set("PrimaryRayCondition", "Expression");
model.component("comp1").physics("gop").feature("wall2").set("e", "gop.Nrefl>0");
model.component("comp1").physics("gop").feature("wall2").set("Otherwise", "Pass");
// Application Library: Ray_Optics_Module/Applications/solar_dish_receiver_designer

model.component("comp1").physics("gop").create("mir1", "Mirror", 2);
model.component("comp1").physics("gop").feature("mir1").selection().named("mirrors");
// Application Libraries: Ray_Optics_Module/Laser_Cavities/bow_tie_laser_cavity, Ray_Optics_Module/Lenses_Cameras_and_Telescopes/newtonian_telescope

model.component("comp1").physics("gop").create("rpt1", "ReleaseFromPoint", 0);
model.component("comp1").physics("gop").feature("rpt1").set("RayDirectionVector", "Conical");
model.component("comp1").physics("gop").feature("rpt1").set("alphac", "pi/8");
// Application Libraries: Ray_Optics_Module/Lenses_Cameras_and_Telescopes/ray_optics_modeling_fresnel_lens, Ray_Optics_Module/Spectrometers_and_Monochromators (entrance-slit releases)

model.component("comp1").physics("gop").create("relg1", "ReleaseGrid", -1);
model.component("comp1").physics("gop").feature("relg1").set("GridType", "Hexapolar");
model.component("comp1").physics("gop").feature("relg1").set("Rc", "D_pupil/2");
model.component("comp1").physics("gop").feature("relg1").set("Ncr", "10");
// one relg per field angle; Application Libraries: Ray_Optics_Module/Lenses_Cameras_and_Telescopes/double_gauss_lens, Ray_Optics_Module/Laser_Cavities/bow_tie_laser_cavity

model.component("comp1").physics("gop").create("ill1", "IlluminatedSurface", 2);
model.component("comp1").physics("gop").feature("ill1").set("IncidentRayDirectionVector", "SolarRadiation");
model.component("comp1").physics("gop").feature("ill1").set("Nr", "100000");
// Application Libraries: Ray_Optics_Module/Solar_Radiation/solar_dish_receiver, Ray_Optics_Module/Solar_Radiation/vdara_caustic_surface

model.component("comp1").physics("gop").create("rele1", "ReleaseFromElectricField", 2);
model.component("comp1").physics("gop").feature("rele1").set("E_src", "root.comp1.ewfd.Ex");
// Ray Tracing study uses the Wavelength Domain solution in 'Values of variables not solved for'; Application Library: Ray_Optics_Module/Tutorials/plane_em_wave_to_ray_release

model.component("comp1").physics("gop").create("grat1", "Grating", 1);
model.component("comp1").physics("gop").feature("grat1").set("dg", "1[mm]/600");
model.component("comp1").physics("gop").feature("grat1").set("RaysToRelease", "Reflected");
// Application Libraries: Ray_Optics_Module/Spectrometers_and_Monochromators/czerny_turner_monochromator, Ray_Optics_Module/Verification_Examples/diffraction_grating, Ray_Optics_Module/Tutorials/rowland_circle_spectrometer

model.component("comp1").physics("gop").create("xgrat1", "CrossGrating", 2);
model.component("comp1").physics("gop").feature("xgrat1").set("RaysToRelease", "Reflected");
// Application Library: Ray_Optics_Module/Spectrometers_and_Monochromators/cross_grating_echelle_spectrograph

model.component("comp1").physics("gop").create("lwav1", "LinearWaveRetarder", 2);
model.component("comp1").physics("gop").feature("lwav1").set("deltal", "delta");
// sweep delta to turn linear into elliptical/circular polarization; Application Library: Ray_Optics_Module/Tutorials/linear_wave_retarder

